$form->addElement(new Zend_Form_Element_Captcha('captcha', array(
    'label'   => 'Are you human?',
    'captcha' => array(
        'captcha'   => 'SiteVerify',
        'provider'  => 'turnstile',
        'siteKey'   => $config->captcha->siteKey,
        'secretKey' => $config->captcha->secretKey,
        'attribs'   => array('theme' => 'dark'),
    ),
)));

if ($form->isValid($this->getRequest()->getPost())) {
    // the token was verified by the service
}
